def asm(lines):
    """lines: list of either ('label', name) or (mnemonic, operands...) as raw strings"""
    labels = {}
    # pass 1
    pc = 0x200
    for ln in lines:
        if isinstance(ln, tuple) and ln[0] == 'label':
            labels[ln[1]] = pc
        else:
            pc += 2
    return labels

# We'll do a tiny assembler with explicit operands.
# Instruction forms:
#  'CLS', 'RET', 'SYS n' (unused), 'JP n'/'JP V0,n', 'CALL n', 'SE Vx,k', 'SNE Vx,k',
#  'SE Vx,Vy', 'LD Vx,k', 'ADD Vx,k', 'LD Vx,Vy', 'OR,AND,XOR,ADD Vx,Vy,SUB,VSHR?,SUBN',
#  'DRW Vx,Vy,n', 'SKP Vx', 'SKNP Vx', 'LD I,n', 'JP V0,n', 'RND Vx,k', 'LD Vx,DT',
#  'LD Vx,K', 'LD DT,Vx', 'LD ST,Vx', 'ADD I,Vx', 'LD F,Vx', 'LD B,Vx', 'LD [I],Vx', 'LD Vx,[I]'

import re
def assemble(src_lines):
    labels = {}
    # tokenize: each line "label:" optionally followed by instruction
    items = []
    pc = 0x200
    for raw in src_lines:
        line = raw.split(';')[0].strip()
        if not line: continue
        m = re.match(r'^([A-Za-z_][\w]*):\s*(.*)$', line)
        if m:
            labels[m.group(1)] = pc
            line = m.group(2).strip()
            if not line: continue
        items.append((pc, line))
        pc += 2
    def val(tok, cur):
        tok = tok.strip()
        if tok in labels: return labels[tok]
        if tok.upper().startswith('0X'): return int(tok,16)
        if tok.isdigit(): return int(tok)
        if tok.startswith('-') and tok[1:].isdigit(): return int(tok)
        raise ValueError(tok)
    out = bytearray()
    for cur, line in items:
        parts = re.split(r'\s+', line, maxsplit=1)
        op = parts[0].upper()
        rest = parts[1] if len(parts)>1 else ''
        args = [a.strip() for a in rest.split(',')] if rest else []
        def vreg(a):
            assert a.upper().startswith('V'), a
            return int(a[1:],16)
        if op=='CLS': w=0x00E0
        elif op=='RET': w=0x00EE
        elif op=='JP':
            if args[0].upper()=='V0': w=0xB000 | (val(args[1],cur)&0xFFF)
            else: w=0x1000 | (val(args[0],cur)&0xFFF)
        elif op=='CALL': w=0x2000 | (val(args[0],cur)&0xFFF)
        elif op=='SE':
            if args[1].upper().startswith('V'): w=0x5000 | (vreg(args[0])<<8) | (vreg(args[1])<<4)
            else: w=0x3000 | (vreg(args[0])<<8) | (val(args[1],cur)&0xFF)
        elif op=='SNE':
            if args[1].upper().startswith('V'): w=0x9000 | (vreg(args[0])<<8) | (vreg(args[1])<<4)
            else: w=0x4000 | (vreg(args[0])<<8) | (val(args[1],cur)&0xFF)
        elif op=='LD':
            x=args[0].upper()
            if x=='I': w=0xA000 | (val(args[1],cur)&0xFFF)
            elif x=='[I]': w=0xF055 | (vreg(args[1])<<8)
            elif x=='DT': w=0xF015 | (vreg(args[1])<<8)
            elif x=='ST': w=0xF018 | (vreg(args[1])<<8)
            elif x=='F': w=0xF029 | (vreg(args[1])<<8)
            elif x=='B': w=0xF033 | (vreg(args[1])<<8)
            else:
                r=args[1].upper()
                if r.startswith('DT'): w=0xF007 | (vreg(args[0])<<8)
                elif r=='K': w=0xF00A | (vreg(args[0])<<8)
                elif r.startswith('[I]'): w=0xF065 | (vreg(args[0])<<8)
                elif r.startswith('V'): w=0x8000 | (vreg(args[0])<<8) | (vreg(args[1])<<4) | 0x0
                else: w=0x6000 | (vreg(args[0])<<8) | (val(args[1],cur)&0xFF)
        elif op=='ADD':
            if args[0].upper()=='I': w=0xF01E | (vreg(args[1])<<8)
            else:
                if args[1].upper().startswith('V'): w=0x8000 | (vreg(args[0])<<8)|(vreg(args[1])<<4)|0x4
                else: w=0x7000 | (vreg(args[0])<<8) | (val(args[1],cur)&0xFF)
        elif op in ('OR','AND','XOR','SUB','SHR','SUBN','SHL'):
            base={'OR':0x1,'AND':0x2,'XOR':0x3,'SUB':0x5,'SHR':0x6,'SUBN':0x7,'SHL':0xE}[op]
            if op in ('SHR','SHL'):
                # allow SHR Vx (Vx >>=1) or SHR Vx,Vy
                if len(args)==1: w=0x8000|(vreg(args[0])<<8)|(vreg(args[0])<<4)|base
                else: w=0x8000|(vreg(args[0])<<8)|(vreg(args[1])<<4)|base
            else:
                w=0x8000|(vreg(args[0])<<8)|(vreg(args[1])<<4)|base
        elif op=='DRW': w=0xD000 | (vreg(args[0])<<8)|(vreg(args[1])<<4)|(int(args[2],10)&0xF)
        elif op=='SKP': w=0xE09E | (vreg(args[0])<<8)
        elif op=='SKNP': w=0xE0A1 | (vreg(args[0])<<8)
        elif op=='RND': w=0xC000 | (vreg(args[0])<<8) | (val(args[1],cur)&0xFF)
        elif op=='SYS': w=0x0000 | (val(args[0],cur)&0xFFF)
        else: raise ValueError('unknown op '+op)
        out += bytes([(w>>8)&0xFF, w&0xFF])
    return bytes(out), labels

